class TreeNode:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class AVLTree:
    def __init__(self):
        self.root = None

    def _height(self, node):
        if not node:
            return 0
        return max(self._height(node.left), self._height(node.right)) + 1

    def _balance_factor(self, node):
        if not node:
            return 0
        return self._height(node.left) - self._height(node.right)

    def _rotate_left(self, z):
        y = z.right
        T2 = y.left

        # Perform rotation
        y.left = z
        z.right = T2

        return y

    def _rotate_right(self, z):
        y = z.left
        T3 = y.right

        # Perform rotation
        y.right = z
        z.left = T3

        return y

    def _balance(self, node):
        if not node:
            return node

        balance = self._balance_factor(node)

        # Left heavy tree
        if balance > 1:
            if self._balance_factor(node.left) < 0:
                node.left = self._rotate_left(node.left)
            return self._rotate_right(node)

        # Right heavy tree
        if balance < -1:
            if self._balance_factor(node.right) > 0:
                node.right = self._rotate_right(node.right)
            return self._rotate_left(node)

        return node

    def _insert(self, node, key):
        if not node:
            return TreeNode(key)

        if key < node.key:
            node.left = self._insert(node.left, key)
        else:
            node.right = self._insert(node.right, key)

        return self._balance(node)

    def insert(self, key):
        self.root = self._insert(self.root, key)

    def _inorder_traversal(self, node):
        if not node:
            return []
        return self._inorder_traversal(node.left) + [node.key] + self._inorder_traversal(node.right)

    def inorder(self):
        return self._inorder_traversal(self.root)

if __name__ == "__main__":
    tree = AVLTree()

    # Input example: an unbalanced array
    input_array = [30, 20, 40, 10, 25, 35, 50, 5, 15]

    # Prepare the AVL Tree
    for key in input_array:
        tree.insert(key)

    # Output the balanced AVL tree (inorder traversal)
    print("Inorder traversal of the balanced AVL tree:", tree.inorder())

